/* QUINTA service worker — generated by vite.config.ts from resources/sw/sw.template.js. Do not edit public/sw.js. */
const VERSION = 'quinta-__VERSION__';
const RUNTIME = 'quinta-runtime';
const PRECACHE = __PRECACHE__;

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches
            .open(VERSION)
            .then((cache) => cache.addAll(PRECACHE.map((url) => new Request(url, { cache: 'reload' }))))
            .then(() => self.skipWaiting()),
    );
});

self.addEventListener('activate', (event) => {
    // Only Cache Storage entries from older versions are removed. IndexedDB is never touched.
    event.waitUntil(
        caches
            .keys()
            .then((keys) => Promise.all(keys.filter((k) => k.startsWith('quinta-') && k !== VERSION && k !== RUNTIME).map((k) => caches.delete(k))))
            .then(() => self.clients.claim()),
    );
});

self.addEventListener('message', async (event) => {
    if (event.data && event.data.type === 'status') {
        const cache = await caches.open(VERSION);
        const keys = await cache.keys();
        event.source && event.source.postMessage({ type: 'status', version: VERSION, ready: keys.length >= PRECACHE.length });
    }
});

function isApi(url) {
    return url.pathname.startsWith('/api/');
}

self.addEventListener('fetch', (event) => {
    const request = event.request;
    if (request.method !== 'GET') return;
    const url = new URL(request.url);
    if (url.origin !== self.location.origin || isApi(url) || /^\/(account|login|logout)(\/|$)/.test(url.pathname)) return;

    // App navigations (any internal view): network first with a short timeout, then the cached shell.
    if (request.mode === 'navigate') {
        event.respondWith(
            (async () => {
                try {
                    const controller = new AbortController();
                    const timer = setTimeout(() => controller.abort(), 3000);
                    const response = await fetch(request, { signal: controller.signal });
                    clearTimeout(timer);
                    if (response.ok) {
                        const cache = await caches.open(VERSION);
                        cache.put('/', response.clone());
                    }
                    return response;
                } catch (e) {
                    const cached = await caches.match('/', { cacheName: VERSION });
                    return cached || (await caches.match('/')) || Response.error();
                }
            })(),
        );
        return;
    }

    // Versioned assets and static files: cache first. Lazy assets (3D) land in the runtime cache on first use.
    event.respondWith(
        (async () => {
            const hit = await caches.match(request);
            if (hit) return hit;
            const response = await fetch(request);
            if (response.ok && (url.pathname.startsWith('/build/') || url.pathname.startsWith('/assets/'))) {
                const cache = await caches.open(RUNTIME);
                cache.put(request, response.clone());
            }
            return response;
        })(),
    );
});
